import java.util.Scanner;

public class Main {
    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        if (!sc.hasNextInt()) return;
        int a = sc.nextInt();
        int b = sc.nextInt();
        int c = sc.nextInt();
        int d = sc.nextInt();

        boolean possible = false;
        for (int k = 1; k * d <= c; k++) {
            int milk = c - k * d;
            if (milk >= a && milk <= b) {
                possible = true;
                break;
            }
        }

        if (possible) {
            System.out.println("S");
        } else {
            System.out.println("N");
        }
    }
}
